{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "SearchPlugins",
    "description": "Search the plugins the user could install (or already has): marketplace plugins bundling connectors and skills. Say what you're looking for in natural language and results come back ranked by relevance, each with its STABLE plugin id, install state, and what it includes. Use this to discover a capability (Linear, Notion, writing Word documents, …) or to check whether a plugin is installed. Inspect one result with GetPlugin; connector runtime statuses (connected/needsAuth) live in GetMcpServerStatus. This is read-only and never needs the user's permission.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "Optional. What you're looking for, in natural language (e.g. \"manage linear issues\" or \"write word documents\") — results come back ranked by relevance. Omit to list the whole catalog."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "GetMcpServerStatus",
    "description": "The runtime status of the user's installed MCP servers (connected / needsAuth / error, per account). Pass server_id (the server identifier, NEVER a display name) for one server; omit it to list everything. Use this to see which connectors still need authentication, to find the identifier a lifecycle tool needs — the same one GetDynamicTools and CallDynamicTool address — or to check a connector after installing or authenticating. Read-only and never needs the user's permission.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "server_id": {
          "type": "string",
          "description": "Optional. One server to report on. The server identifier shown by GetMcpServerStatus — the same identifier GetDynamicTools and CallDynamicTool address, e.g. \"dashboard-team-1-Slack\". Never a display name. Omit to list every installed server."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "TodoWrite",
    "description": "Your task queue: the durable list of everything the user has asked for, across all your parallel streams of work.\n\nWhen to use:\n- The moment a request arrives, record it as a todo before dispatching or starting it.\n- Update statuses in real time: in_progress when its work starts, completed the moment its result is delivered to the user, cancelled when the user drops it or changes their mind.\n- On every wake (a user message or a finished background task), reconcile the list first: what's running, what landed, what to dispatch next.\n\nStates and parallelism:\n- pending: not yet started. in_progress: actively being worked, by you or a background worker. completed: result delivered to the user. cancelled: no longer needed.\n- SEVERAL todos are normally in_progress at once — one per independent stream running in parallel (each dispatched worker, plus at most one thing you are doing inline). Never serialize independent streams just to keep a single one in_progress.\n- Keep the list current rather than perfect: cancel stale items instead of leaving them pending, and prune long-finished ones when the list gets noisy.\n\nSkip it for purely conversational replies and trivial one-step lookups you answer inline immediately.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "todos": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string",
                "description": "Unique identifier for the TODO item"
              },
              "content": {
                "type": "string",
                "description": "The description/content of the todo item"
              },
              "status": {
                "type": "string",
                "enum": [
                  "pending",
                  "in_progress",
                  "completed",
                  "cancelled"
                ],
                "description": "The current status of the TODO item"
              }
            },
            "required": [
              "id",
              "content",
              "status"
            ]
          },
          "minItems": 2,
          "description": "Array of TODO items to update or create"
        },
        "merge": {
          "type": "boolean",
          "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
        }
      },
      "required": [
        "todos",
        "merge"
      ]
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "AddMcpServer",
    "description": "Add an MCP server that isn't in the catalog to the user's Cursor account — use this when the user gives you a link or a launch command for a server that SearchPlugins doesn't know. Only call this after the user agrees to add it — confirm with a question widget first, since it changes the user's account configuration and the server can run commands or reach external services on their behalf. Provide EITHER a remote `url` OR a local `command` with `args` (and `env` for secrets) — not both. For a remote server's credentials, use `headers` for static bearer/API-key auth, or `auth` for an OAuth provider that publishes a pre-registered client ID (its `CLIENT_ID`, optional `CLIENT_SECRET`, and `scopes`) instead of supporting dynamic client registration. A remote server runs on the backend; a `command` server runs on your computer, which has node, npm, bun, python3, and uv, so `npx -y <pkg>` and `uvx <pkg>` both work — install anything else it needs with Shell first. That command also runs in this user's other agents, so say so when you confirm. Ask the user for the exact endpoint or command and any secrets rather than guessing; if you only have a link, open it first (WebFetch) to find the connection details. Newly added tools become available to you on your next message.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "description": "A short, unique name for the server, e.g. \"superpowers\"."
        },
        "url": {
          "type": "string",
          "minLength": 1,
          "description": "For a remote server: its MCP endpoint URL (https). Provide url OR command, not both."
        },
        "headers": {
          "type": "object",
          "description": "Optional HTTP headers for a remote server with static bearer/API-key auth, e.g. { \"Authorization\": \"Bearer <token>\" }. Ask the user for any secret rather than guessing."
        },
        "auth": {
          "type": "object",
          "properties": {
            "CLIENT_ID": {
              "type": "string",
              "minLength": 1,
              "description": "The OAuth client ID the server publishes for pre-registered clients."
            },
            "CLIENT_SECRET": {
              "type": "string",
              "description": "Optional OAuth client secret. Ask the user for it rather than guessing; many public clients need none."
            },
            "scopes": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Optional OAuth scopes to request, e.g. [\"tweet.read\", \"offline.access\"]."
            }
          },
          "required": [
            "CLIENT_ID"
          ],
          "description": "Optional OAuth client settings for a remote server whose provider does not support dynamic client registration and instead publishes a pre-registered client ID. Use `headers` for static bearer/API-key auth; use `auth` only for OAuth. Remote servers only — never combine with `command`."
        },
        "command": {
          "type": "string",
          "minLength": 1,
          "description": "For a local (stdio) server: the executable to run on Grok Bot's computer, e.g. \"npx\". Provide command OR url, not both."
        },
        "args": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Arguments for the stdio command, e.g. [\"-y\", \"@acme/mcp-server\"]."
        },
        "env": {
          "type": "object",
          "description": "Environment variables for the stdio command, e.g. { \"API_KEY\": \"<token>\" }. Ask the user for any secret rather than guessing."
        }
      },
      "required": [
        "name"
      ]
    }
  }
}

